/**
 * Guidance state machine — pure computation, no React dependencies.
 *
 * Core types and helper functions for confidence-gated turn-by-turn navigation.
 * Drives the live guidance UI overlay and reroute logic.
 */

import type { DirectionStep, NormalizedNodeRecord } from '../domain/navGraph';
import type { PathResult } from '../domain/navGraph';
import type { RouteSessionReadyState } from './routeSessionState';
import type { NormalizedPoint } from '../../src/shared/gps';

// ============================================================
// Core types
// ============================================================

/**
 * GPS and heading confidence classification.
 *
 * Used by `deriveConfidence` to determine how aggressively
 * the guidance engine trusts the current position fix.
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';

/**
 * Phase of the guidance state machine.
 *
 * State transitions are governed by `deriveNextPhase`:
 * - `idle`          → Initial state; no route loaded
 * - `low-confidence` → Route loaded, but GPS/heading signal is weak
 * - `guiding`       → Route active with confident position; advancing steps
 * - `rerouting`     → Off-route detected, computing new path
 * - `arrived`        → User has reached the destination
 */
export type GuidancePhase =
  | 'idle'
  | 'low-confidence'
  | 'guiding'
  | 'rerouting'
  | 'arrived';

/**
 * Core guidance state for live navigation.
 *
 * Carries the route, current position, and confidence signals needed
 * to drive step advancement and reroute decisions.
 */
export interface GuidanceState {
  phase: GuidancePhase;
  /** The route being followed — must be in 'ready' phase. */
  route: RouteSessionReadyState;
  /** Index of the active DirectionStep (0-based). */
  currentStepIndex: number;
  /** User's current position in normalized [0,1] map space. */
  snappedPosition: NormalizedPoint;
  /** Nearest walkable node ID to the snapped position. */
  snappedNodeId: string;
  /** Device compass heading in degrees (0–360), null if unavailable. */
  heading: number | null;
  /** Heading accuracy in degrees, null if unavailable. */
  headingConfidence: number | null;
  /** Classification of current position fix quality. */
  positionConfidence: ConfidenceLevel;
  /** Unix timestamp (ms) of the last position fix. */
  lastFixTimestamp: number;
  /** Unix timestamp (ms) when off-route was first detected, null if on-route. */
  offRouteDetectedAt: number | null;
  /** Consecutive fixes where off-route was detected. */
  offRouteFixCount: number;
  /** Result of the last reroute computation, null if no reroute has been attempted. */
  rerouteResult: PathResult | null;
}

// ============================================================
// Helper function input types
// ============================================================

export interface PositionFix {
  readonly isConfident: boolean;
  readonly accuracyMeters: number | null;
}

export interface HeadingFix {
  readonly headingDegrees: number | null;
  readonly accuracyDegrees: number | null;
}

// ============================================================
// Pure helper functions
// ============================================================

/**
 * Derive the GPS/heading confidence level from position and heading fixes.
 *
 * Confidence levels:
 * - `high`:   GPS fix is confident AND heading accuracy ≤ 15°
 * - `medium`: GPS fix is confident but heading is missing or unreliable (> 15°)
 * - `low`:    GPS fix not confident but finite (accuracy exists)
 * - `none`:   No GPS fix or infinite accuracy
 */
export function deriveConfidence(
  positionFix: PositionFix,
  headingFix: HeadingFix,
): ConfidenceLevel {
  // none: no GPS fix (null) or infinite accuracy
  if (positionFix.accuracyMeters == null || !Number.isFinite(positionFix.accuracyMeters)) {
    return 'none';
  }

  // low: GPS fix not confident but finite (accuracy exists but > threshold)
  if (!positionFix.isConfident) {
    return 'low';
  }

  // medium: GPS confident but heading missing or unreliable
  if (
    headingFix.headingDegrees == null
    || headingFix.accuracyDegrees == null
    || !Number.isFinite(headingFix.accuracyDegrees)
    || headingFix.accuracyDegrees > 15
  ) {
    return 'medium';
  }

  // high: GPS confident AND heading reliable (≤ 15°)
  return 'high';
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Build an ordered coordinate lookup from a path and its route state.
 * Looks for a nodeById map on the path (production) or falls back to
 * extracting coordinates directly from the node IDs using route.path.nodeById.
 *
 * The path may carry nodeById as an extended property (production path),
 * or the coordinates are resolved via route.path.nodeById (test path).
 */
function buildCoordLookup(
  path: PathResult,
  route: RouteSessionReadyState,
): Map<number, { x: number; y: number }> {
  const coords = new Map<number, { x: number; y: number }>();

  // Try path.nodeById first (production extension pattern)
  const pathAsExtended = path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  if (pathAsExtended.nodeById && typeof pathAsExtended.nodeById.get === 'function') {
    const nodeById = pathAsExtended.nodeById;
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
    return coords;
  }

  // Fallback: resolve via route.path.nodeById (test / production NormalizedNavGraph pattern)
  const routePathAsGraph = route.path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  const nodeById = routePathAsGraph.nodeById;
  if (nodeById && typeof nodeById.get === 'function') {
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
  }

  return coords;
}

/**
 * Compute perpendicular (orthogonal) distance from a point to a line segment.
 *
 * Returns the minimum distance from `point` to any point on the segment
 * between `segStart` and `segEnd`.
 *
 * Uses the standard point-to-segment formula:
 * Let t = dot(P - segStart, segEnd - segStart) / |segEnd - segStart|²
 * Clamp t to [0, 1] (to stay on the segment)
 * Closest point = segStart + t * (segEnd - segStart)
 * Distance = |P - closest_point|
 */
function pointToSegmentDistance(
  point: NormalizedPoint,
  segStart: { x: number; y: number },
  segEnd: { x: number; y: number },
): number {
  const dx = segEnd.x - segStart.x;
  const dy = segEnd.y - segStart.y;
  const lenSq = dx * dx + dy * dy;

  // Degenerate segment (start === end): return distance to the point
  if (lenSq === 0) {
    return Math.sqrt((point.x - segStart.x) ** 2 + (point.y - segStart.y) ** 2);
  }

  // Parameter t for the projection of P onto the segment line
  const t = Math.max(
    0,
    Math.min(
      1,
      ((point.x - segStart.x) * dx + (point.y - segStart.y) * dy) / lenSq,
    ),
  );

  const closestX = segStart.x + t * dx;
  const closestY = segStart.y + t * dy;

  return Math.sqrt((point.x - closestX) ** 2 + (point.y - closestY) ** 2);
}

// ============================================================
// Public route-geometry helpers
// ============================================================

/**
 * Returns true when the user's position is off the active route segment.
 *
 * Detects deviation by measuring perpendicular distance from the current
 * position to the current path segment (from path.nodeIds[currentStepIndex]
 * to path.nodeIds[currentStepIndex + 1]).
 *
 * @param position     User's current snapped position
 * @param currentStepIndex  Which step in the route is active
 * @param path         The current route path
 * @param route        The route session state (provides normalized graph nodeById)
 * @param threshold    Deviation threshold in normalized units (default: 0.05)
 */
export function isOffRoute(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  threshold = 0.05,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // When at or beyond the last segment, use distance to the final node
  if (currentStepIndex >= path.nodeIds.length - 1) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;

    const dist = Math.sqrt(
      (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
    );
    return dist > threshold;
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(currentStepIndex + 1);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance > threshold;
}

/**
 * Returns true when the user has reached the waypoint at the start of the next step.
 *
 * Uses the same perpendicular-distance approach as `isOffRoute` but with a
 * smaller threshold so that near-passing doesn't trigger an advance mid-segment.
 *
 * @param position        User's current snapped position
 * @param currentStepIndex  Index of the current step (advance check goes to step + 1)
 * @param path            The current route path
 * @param route           The route session state (provides normalized graph nodeById)
 * @param advanceThreshold  Proximity threshold for triggering advance (default: 0.03)
 */
export function shouldAdvanceStep(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  advanceThreshold = 0.03,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // If the next step index is beyond the node list, use the last node
  const nextStepIdx = currentStepIndex + 1;
  if (nextStepIdx >= path.nodeIds.length) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;
    return (
      Math.sqrt(
        (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
      ) <= advanceThreshold
    );
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(nextStepIdx);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance <= advanceThreshold;
}

/**
 * Derive the next phase from current state and signals.
 *
 * Phase transition rules:
 * - `idle`          → `isConfident` ? 'guiding' : 'low-confidence'
 * - `low-confidence` → `isConfident` ? 'guiding' : stay 'low-confidence'
 * - `guiding`       → `hasArrived` ? 'arrived'
 *                    → `offRouteFixCount >= rerouteConfirmFixes` ? 'rerouting'
 *                    → stay 'guiding'
 * - `rerouting`     → always transitions to 'guiding' (assumes reroute succeeded)
 * - `arrived`       → stays 'arrived'
 *
 * @param state                  Current guidance state
 * @param isConfident            Whether current position is high or medium confidence
 * @param hasArrived             Whether the user has arrived at the destination
 * @param offRouteFixCount       Number of consecutive off-route position fixes
 * @param rerouteConfirmFixes    Fixes required before triggering reroute (default: 3)
 */
export function deriveNextPhase(
  state: GuidanceState,
  isConfident: boolean,
  hasArrived: boolean,
  offRouteFixCount: number,
  rerouteConfirmFixes = 3,
): GuidancePhase {
  switch (state.phase) {
    case 'idle':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'low-confidence':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'guiding':
      if (hasArrived) return 'arrived';
      if (offRouteFixCount >= rerouteConfirmFixes) return 'rerouting';
      return 'guiding';

    case 'rerouting':
      // Assumes the caller has set rerouteResult; transitions back to guiding
      return 'guiding';

    case 'arrived':
      return 'arrived';
  }
}

/**
 * Return the active DirectionStep for the current step index.
 *
 * Returns null when there is no active route, no directions have been generated,
 * or the current step index is out of bounds.
 */
export function getActiveStep(state: GuidanceState): DirectionStep | null {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready') return null;
  if (!route.directions) return null;
  const { steps } = route.directions;
  if (currentStepIndex < 0 || currentStepIndex >= steps.length) return null;
  return steps[currentStepIndex] ?? null;
}

import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { resolve } from 'node:path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@shared': resolve(__dirname, '../src/shared'),
      '@client': resolve(__dirname, '../src/client'),
    },
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
  },
});

/**
 * DestinationPicker — building/floor/node accordion with fuzzy text search.
 * Pressing a node calls onNodeSelect. "Set Start" / "Set Destination" toggle
 * in header reflects the activeField from RouteSelection.
 */

import { useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { useLocationSearch } from '../../hooks/useLocationSearch';
import type { NormalizedNavGraph } from '../../domain/navGraph';
import type { NavNode } from '../../../src/shared/types';
import type { RouteSelection } from '../../hooks/useRouteSelection';

const DEBOUNCE_MS = 300;

interface Props {
  graph: NormalizedNavGraph;
  selection: RouteSelection;
  onNodeSelect: (node: NavNode) => void;
}

const TYPE_BADGE: Record<string, string> = {
  room: '📍',
  entrance: '🚪',
  elevator: '🛗',
  restroom: '🚻',
  landmark: '⭐',
  stairs: '⬆️',
  ramp: '♿',
  junction: '⬡',
  hallway: '─',
};

const ACCESSIBLE_ICON = '♿';

export function DestinationPicker({ graph, selection, onNodeSelect }: Props) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  const { buildings, totalMatches } = useLocationSearch(graph, debouncedQuery);

  const activeLabel = selection.activeField === 'start' ? 'Set Start' : 'Set Destination';
  const otherLabel = selection.activeField === 'start' ? 'Set Destination' : 'Set Start';

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerLabel}>{activeLabel}</Text>
        <Text style={styles.resultCount}>
          {totalMatches} {totalMatches === 1 ? 'result' : 'results'}
        </Text>
      </View>

      {/* Search input */}
      <TextInput
        style={styles.searchInput}
        placeholder="Search location..."
        placeholderTextColor="#64748b"
        value={query}
        onChangeText={setQuery}
        autoCapitalize="none"
        autoCorrect={false}
      />

      {/* Active field indicator */}
      <View style={styles.fieldToggle}>
        <Text style={styles.fieldText}>Picking: </Text>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'start' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('start')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'start' && styles.fieldChipTextActive]}>
            Start {selection.start ? `(${selection.start.label})` : ''}
          </Text>
        </Pressable>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'destination' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('destination')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'destination' && styles.fieldChipTextActive]}>
            Dest {selection.destination ? `(${selection.destination.label})` : ''}
          </Text>
        </Pressable>
        {(selection.start || selection.destination) && (
          <Pressable style={styles.swapButton} onPress={selection.swap}>
            <Text style={styles.swapButtonText}>⇄ Swap</Text>
          </Pressable>
        )}
      </View>

      {/* Results */}
      <FlatList
        data={buildings}
        keyExtractor={item => String(item.buildingId)}
        style={styles.list}
        renderItem={({ item: building }) => (
          <BuildingAccordion
            building={building}
            onNodeSelect={onNodeSelect}
          />
        )}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {debouncedQuery ? 'No locations match your search.' : 'No locations available.'}
          </Text>
        }
      />
    </View>
  );
}

/* ─── Sub-components ─── */

interface BuildingAccordionProps {
  building: import('../../hooks/useLocationSearch').SearchBuilding;
  onNodeSelect: (node: NavNode) => void;
}

function BuildingAccordion({ building, onNodeSelect }: BuildingAccordionProps) {
  const [expanded, setExpanded] = useState(false);

  return (
    <View style={styles.buildingSection}>
      <Pressable style={styles.buildingHeader} onPress={() => setExpanded(e => !e)}>
        <View style={styles.buildingInfo}>
          <Text style={styles.buildingName}>{building.buildingName}</Text>
          <Text style={styles.buildingMeta}>
            {building.floors.length} {building.floors.length === 1 ? 'floor' : 'floors'} ·{' '}
            {building.floors.reduce((sum, f) => sum + f.nodes.length, 0)} locations
          </Text>
        </View>
        <Text style={styles.chevron}>{expanded ? '▼' : '▶'}</Text>
      </Pressable>

      {expanded && (
        <View style={styles.floorsContainer}>
          {building.floors.map(floor => (
            <FloorSection key={floor.floorId} floor={floor} onNodeSelect={onNodeSelect} />
          ))}
        </View>
      )}
    </View>
  );
}

interface FloorSectionProps {
  floor: import('../../hooks/useLocationSearch').SearchFloor;
  onNodeSelect: (node: NavNode) => void;
}

function FloorSection({ floor, onNodeSelect }: FloorSectionProps) {
  return (
    <View style={styles.floorSection}>
      <Text style={styles.floorHeader}>Floor {floor.floorNumber}</Text>
      {floor.nodes.map(sn => (
        <NodeRow key={sn.node.id} searchNode={sn} onPress={() => onNodeSelect(sn.node)} />
      ))}
    </View>
  );
}

interface NodeRowProps {
  searchNode: import('../../hooks/useLocationSearch').SearchNode;
  onPress: () => void;
}

function NodeRow({ searchNode, onPress }: NodeRowProps) {
  const { node, buildingName, floorNumber } = searchNode;
  const badge = TYPE_BADGE[node.type] ?? '📍';
  const isAccessible = node.type === 'elevator' || node.type === 'ramp';

  return (
    <Pressable style={styles.nodeRow} onPress={onPress}>
      <Text style={styles.nodeBadge}>{badge}</Text>
      <View style={styles.nodeInfo}>
        <Text style={styles.nodeLabel}>{node.label}</Text>
        <Text style={styles.nodeSubtext}>
          {buildingName} · Floor {floorNumber}
          {node.roomNumber ? ` · Room ${node.roomNumber}` : ''}
        </Text>
      </View>
      {isAccessible && <Text style={styles.accessibleIcon}>{ACCESSIBLE_ICON}</Text>}
    </Pressable>
  );
}

/* ─── Styles (dark theme, campusnav palette) ─── */

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#020617' },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 16, paddingTop: 12, paddingBottom: 8 },
  headerLabel: { color: '#f8fafc', fontSize: 18, fontWeight: '700' },
  resultCount: { color: '#64748b', fontSize: 13 },
  searchInput: {
    marginHorizontal: 16,
    marginBottom: 8,
    backgroundColor: '#0f172a',
    borderColor: '#1e293b',
    borderWidth: 1,
    borderRadius: 10,
    paddingHorizontal: 14,
    paddingVertical: 10,
    color: '#f8fafc',
    fontSize: 15,
  },
  fieldToggle: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingBottom: 10, gap: 8 },
  fieldText: { color: '#94a3b8', fontSize: 13 },
  fieldChip: { backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  fieldChipActive: { backgroundColor: '#1e3a5f', borderColor: '#38bdf8' },
  fieldChipText: { color: '#94a3b8', fontSize: 12 },
  fieldChipTextActive: { color: '#38bdf8', fontWeight: '600' },
  swapButton: { marginLeft: 'auto', backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  swapButtonText: { color: '#94a3b8', fontSize: 12 },
  list: { flex: 1 },
  emptyText: { color: '#475569', fontSize: 14, textAlign: 'center', marginTop: 40 },
  buildingSection: { borderBottomColor: '#1e293b', borderBottomWidth: 1 },
  buildingHeader: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 12 },
  buildingInfo: { flex: 1 },
  buildingName: { color: '#f8fafc', fontSize: 16, fontWeight: '600' },
  buildingMeta: { color: '#64748b', fontSize: 12, marginTop: 2 },
  chevron: { color: '#38bdf8', fontSize: 12 },
  floorsContainer: { backgroundColor: '#0a0f1e', paddingLeft: 16 },
  floorSection: { paddingVertical: 6 },
  floorHeader: { color: '#475569', fontSize: 11, fontWeight: '600', letterSpacing: 1, paddingHorizontal: 16, paddingVertical: 4, textTransform: 'uppercase' },
  nodeRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 10, gap: 10 },
  nodeBadge: { fontSize: 16, width: 24, textAlign: 'center' },
  nodeInfo: { flex: 1 },
  nodeLabel: { color: '#e2e8f0', fontSize: 14, fontWeight: '500' },
  nodeSubtext: { color: '#64748b', fontSize: 11, marginTop: 2 },
  accessibleIcon: { fontSize: 14 },
});

/**
 * RoutePreview — step-by-step directions grouped by floor.
 *
 * Props:
 * - directions: DirectionsResult from the route session
 * - floorMap: Map<floorId, NavFloor> from the normalized graph
 * - accessibleMode: boolean to highlight accessible path elements
 * - onFloorChange: callback to switch the active floor
 */

import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { groupDirectionSections } from '../../routing/directionSections';
import type { DirectionsResult, DirectionSection, DirectionStep } from '../../domain/navGraph';
import type { NavFloor } from '../../../src/shared/types';

/* ─── Icons ─── */

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

/* ─── Step icon color ─── */

function iconColor(step: DirectionStep, accessibleMode: boolean): string {
  if (step.isAccessibleSegment) return '#facc15'; // amber for accessible segments
  if (step.icon === 'arrive') return '#4ade80'; // green for arrival
  if (accessibleMode && (step.icon === 'elevator' || step.icon === 'ramp')) return '#facc15';
  return '#38bdf8'; // cyan for standard
}

/* ─── Duration formatting ─── */

function formatDuration(sec: number): string {
  if (sec < 60) return `${sec}s`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return s > 0 ? `${m}m ${s}s` : `${m}m`;
}

/* ─── Distance formatting (normalized → approximate meters) ─── */

function formatDistance(norm: number): string {
  // Normalized coordinate space → approximate real distance
  // Assume campus coordinate space roughly maps to 50m per unit
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/* ─── Props ─── */

interface Props {
  directions: DirectionsResult;
  accessibleMode: boolean;
}

/* ─── Component ─── */

export function RoutePreview({ directions, accessibleMode }: Props) {
  const sections = groupDirectionSections(directions.steps);

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Route Preview</Text>
        <View style={styles.summaryRow}>
          <Text style={styles.summaryText}>
            {formatDistance(directions.totalDistanceNorm)}
          </Text>
          <Text style={styles.summaryDivider}>·</Text>
          <Text style={styles.summaryText}>
            {formatDuration(directions.totalDurationSec)}
          </Text>
          <Text style={styles.summaryDivider}>·</Text>
          <Text style={styles.stepCount}>{directions.steps.length} steps</Text>
        </View>
      </View>

      {/* Sections */}
      <FlatList
        data={sections}
        keyExtractor={item => String(item.floorId)}
        style={styles.sectionList}
        renderItem={({ item: section }) => (
          <FloorSectionView section={section} accessibleMode={accessibleMode} />
        )}
        ItemSeparatorComponent={() => <View style={styles.sectionSeparator} />}
        ListEmptyComponent={
          <Text style={styles.emptyText}>No directions available.</Text>
        }
