import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { resolve } from 'node:path';

// Babel transform plugin for .tsx files — needed because Vite 7's oxc
// backend (used by @vitejs/plugin-react) does not parse TypeScript
// `import type` syntax.  We prepend this so Babel runs first with
// @babel/preset-typescript and handles the TS/TSX parsing; oxc then
// only needs to handle the JSX output.
function babelForTsx() {
  return {
    name: 'vite:babel-tsx',
    enforce: 'pre' as const,
    async transform(code, id) {
      if (!id.endsWith('.tsx')) return null;
      const babel = await import('@babel/core');
      const result = await babel.transformAsync(code, {
        filename: id,
        presets: [
          ['@babel/preset-typescript', { isTSX: true, allExtensions: true }],
        ],
        plugins: [
          ['@babel/plugin-transform-react-jsx', { runtime: 'automatic' }],
        ],
        sourceType: 'module',
        parserOpts: {
          plugins: ['jsx', 'typescript'],
        },
      });
      return result ? { code: result.code!, map: result.map } : null;
    },
  };
}

export default defineConfig({
  plugins: [react(), babelForTsx()],
  resolve: {
    alias: {
      '@shared': resolve(__dirname, '../src/shared'),
      '@client': resolve(__dirname, '../src/client'),
    },
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
  },
});

