import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { resolve } from 'node:path';

// @babel/preset-typescript must be loaded lazily (CJS) to avoid
// "Unexpected token 'typeof'" when vitest itself parses this .ts config.
async function getPresetTypescript() {
  const mod = await import('@babel/preset-typescript');
  return mod.default ?? mod;
}

// Babel options injected into @vitejs/plugin-react so that its Babel
// transform (normally skipped on Vite 7 because oxc handles JSX)
// is used for .tsx files — which allows TypeScript `import type`
// syntax to parse correctly.
const babelOptions = () => ({
  presets: [
    [getPresetTypescript, { isTSX: true, allExtensions: true }],
  ],
});

export default defineConfig({
  plugins: [react({ babel: babelOptions })],
  resolve: {
    alias: {
      '@shared': resolve(__dirname, '../src/shared'),
      '@client': resolve(__dirname, '../src/client'),
