import type { TransformOptions } from '@babel/core';

export default defineConfig({
  plugins: [
    react(),
    // Babel transform for .tsx files — @babel/preset-typescript handles
    // the TypeScript `import type` syntax that Vite 7's oxc backend can't parse.
    babel({
      filter: /\.tsx$/,
      babelConfig: {
        presets: [
          ['@babel/preset-typescript', { isTSX: true, allExtensions: true }],
        ],
      },
    }),
  ],
  resolve: {
    alias: {
      '@shared': resolve(__dirname, '../src/shared'),
      '@client': resolve(__dirname, '../src/client'),
    },
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
  },
});

import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { resolve } from 'node:path';

export default defineConfig({
  plugins: [
    react(),
    // Inline plugin: Babel handles .tsx files so that TypeScript `import type`
    // syntax is parsed correctly.  Vite 7's default oxc transform can't parse it.
    (function () {
      let babel: typeof import('@babel/core');
      return {
        name: 'vitest:babel-tsx',
        enforce: 'pre' as const,
        async transform(code, id) {
          if (!id.endsWith('.tsx')) return null;
          if (!babel) babel = await import('@babel/core');
          const result = await babel.transformAsync(code, {
            filename: id,
            presets: [
              ['@babel/preset-typescript', { isTSX: true, allExtensions: true }],
            ],
            plugins: [],
            sourceType: 'module',
          });
          return result ? { code: result.code!, map: result.map ?? undefined } : null;
        },
      };
    })(),
  ],
  resolve: {
    alias: {
      '@shared': resolve(__dirname, '../src/shared'),
      '@client': resolve(__dirname, '../src/client'),
    },
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
