export default defineConfig({
  plugins: [
    react(),
    // Fix Vite 7 + Vitest TSX transform: @vitejs/plugin-react conditionally
    // deletes its Babel transform for perf reasons, leaving only oxc.
    // oxc can't parse TypeScript `import type` syntax, so Babel must run.
    // This plugin re-adds the Babel transform after the react plugin.
    {
      name: 'vitest:force-babel-tsx',
      enforce: 'post' as const,
      configResolved(config) {
        // Force the react plugin's Babel transform to stay active
        const reactPlugin = config.plugins.find(
          (p: { name?: string }) => p?.name === 'vite:react-babel',
        );
        if (reactPlugin && !('transform' in reactPlugin)) {
          // Re-add the Babel transform that was deleted
          Object.assign(reactPlugin, {
            async transform(code: string, id: string) {
              if (!id.endsWith('.tsx') && !id.endsWith('.ts')) return null;
              // Dynamic import to avoid top-level CJS issues in config
              const babel = await import('@babel/core');
              const result = await babel.transformAsync(code, {
                filename: id,
                presets: [
                  ['@babel/preset-typescript', { isTSX: id.endsWith('.tsx'), allExtensions: true }],
                ],
                sourceType: 'module',
              });
              return result ? { code: result.code!, map: result.map ?? undefined } : null;
            },
          });
        }
      },
    },
  ],
